const balance = Number($input.first().json.balance) || 0
const containers = Number($('Loop Over Items').first().json.Containers) || 0

const remaining = balance - containers

return [{
  json: {
    ...$input.first().json,
    RequestedContainers: containers,
    CanSubtract: remaining >= 0,
    RemainingBalance: remaining,
  },
}]
